data {
  int<lower=0> N;
  int<lower=0> y[N];
  int<lower=0> n[N];
}
parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}
model {
  alpha ~ normal(0, 1000);
  beta ~ normal(0, 1000);
  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
  target += -2.5 * log(alpha + beta);
}

